%[text] # example for importance sampling of SRP (Ashikhmin–Shirley or Cook-Torrance model)
%[text] モンテカルロ積分に使う乱数の数は `nMCint`
%[text] `それを nMC` 回行って平均と分散を計算し，plotする．（ややこしい）
clc
clear
cls

format long
%[text] ## Monte-Carlo condition & pre-allocation
config.BRDF = 'AS' % AS or CT
config.nMC = 1;
config.gFigs = 2;
% Monte-Carlo integration condition
config.nMCintUni = [1, 5, 1e+1, 5e+1, 1e+2, 5e+2, 1e+3, 5e+3, 1e+4, 5e+4, 1e+5, 5e+5, 1e+6, 5e+6, 1e+7];

srpImp = zeros(config.nMC, 3);
srpUni = zeros(config.nMC, 3);

%[text] ## object
sat = readSC('flatPlate.obj'); %[output:9b1ae34f] %[output:73594590]
showSC(sat, 'Normal', 'on'); %[output:79a4e23f]

nFacet = size(sat.faces,1);
sat.Cd = 0.5 .* ones(nFacet,1);
sat.F0 = 0.5 .* ones(nFacet,1);
sat.nu = 800 .* ones(nFacet,1);
sat.nv = 800 .* ones(nFacet,1);
sat.mCT = 0.145 .* ones(nFacet,1);

const = orbitConst;
d = au2km(1, const) * 10^3; % m
dAU = km2au(d ./ 10^3, const); % AU
S0 = const.S0; % Solar constant, W/m^2
c = const.c; % light speed, m/s
coeff = -S0 / c / dAU^2;
%[text] ## Ashikhmin–Shirley model
thetaI = deg2rad(20);
phiI = deg2rad(-90);
sunB = [sin(thetaI)*cos(phiI), sin(thetaI)*sin(phiI), cos(thetaI)];
sunB = sunB ./ norm(sunB);

%% verification
if strcmp(config.BRDF, 'AS')
    [~, ~, srpCs] = srpASuni(sat, sunB, d, const, 10^7);
elseif strcmp(config.BRDF, 'CT')
    [~, ~, srpCs] = srpCTuni(sat, sunB, d, const, 10^7);
end
srpTrue = srpCs;

stdUni = zeros(length(config.nMCintUni), 3);
meanUni = zeros(length(config.nMCintUni), 3);

%% uniform sampling
tic
for i = 1:length(config.nMCintUni)
    N = config.nMCintUni(i);
    for j = 1:config.nMC
        %[text] ## specular only, uniform distribution
        if strcmp(config.BRDF, 'AS')
            [~, ~, srpCs] = srpASuni(sat, sunB, d, const, N);
        elseif strcmp(config.BRDF, 'CT')
            [~, ~, srpCs] = srpCTuni(sat, sunB, d, const, N);
        end

        srpUni(j,:) = srpCs;
    end
    stdUni(i,:) = std(srpUni, [] ,1);
    meanUni(i,:) = mean(srpUni, 1);
end
toc %[output:130ebbd1]

config.nMCintImp = config.nMCintUni;
stdImp = zeros(length(config.nMCintImp), 3);
meanImp = zeros(length(config.nMCintImp), 3);

%% importance sampling
tic
for i = 1:length(config.nMCintImp)
    N = config.nMCintImp(i);
    for j = 1:config.nMC
        if strcmp(config.BRDF, 'AS')
            [~, ~, srpCs] = srpAS(sat, sunB, d, const, N);
        elseif strcmp(config.BRDF, 'CT')
            [~, ~, srpCs] = srpCT(sat, sunB, d, const, N);
        end

        srpImp(j,:) = srpCs;
    end

    stdImp(i,:) = std(srpImp, [], 1);
    meanImp(i,:) = mean(srpImp, 1);
end

toc %[output:503336b7]

%[text] ## show Figs
figure %[output:4df59e92]
tiledlayout(3,1), nexttile %[output:4df59e92]
plotStd(config.nMCintUni, meanUni(:,1), 3*stdUni(:,1), 'r'), hold on %[output:4df59e92]
plotStd(config.nMCintImp, meanImp(:,1), 3*stdImp(:,1), 'b', 'b'); %[output:4df59e92]

nexttile %[output:4df59e92]
plotStd(config.nMCintUni, meanUni(:,2), 3*stdUni(:,2)); hold on %[output:4df59e92]
plotStd(config.nMCintImp, meanImp(:,2), 3*stdImp(:,2),'b', 'b'); %[output:4df59e92]

nexttile %[output:4df59e92]
plotStd(config.nMCintUni, meanUni(:,3), 3*stdUni(:,3)); hold on %[output:4df59e92]
plotStd(config.nMCintImp, meanImp(:,3), 3*stdImp(:,3), 'b', 'b'); %[output:4df59e92]
legend('uniform', 'importance')
[meanUni(end,:) %[output:group:518c64e4] %[output:554bc606]
    meanImp(end,:)] %[output:group:518c64e4] %[output:554bc606]

%% error
absErrUni = abs(srpTrue - meanUni);
absErrImp = abs(srpTrue - meanImp);
figure %[output:21bda9d9]
tiledlayout(3,1) %[output:21bda9d9]
nexttile %[output:21bda9d9]
plot(log10(config.nMCintUni), absErrUni(:,1), 'rx-') %[output:21bda9d9]
hold on %[output:21bda9d9]
plot(log10(config.nMCintImp), absErrImp(:,1), 'bx-') %[output:21bda9d9]
xlabel('log10(nMCint)'), ylabel('absolute error') %[output:21bda9d9]
nexttile %[output:21bda9d9]
plot(log10(config.nMCintUni), absErrUni(:,2), 'gx-') %[output:21bda9d9]
hold on %[output:21bda9d9]
plot(log10(config.nMCintImp), absErrImp(:,2), 'bx-') %[output:21bda9d9]
xlabel('log10(nMCint)'), ylabel('absolute error') %[output:21bda9d9]
nexttile %[output:21bda9d9]
plot(log10(config.nMCintUni), absErrUni(:,3), 'bx-') %[output:21bda9d9]
hold on %[output:21bda9d9]
plot(log10(config.nMCintImp), absErrImp(:,3), 'bx-') %[output:21bda9d9]
xlabel('log10(nMCint)'), ylabel('absolute error') %[output:21bda9d9]
legend('uniform', 'importance')

relErrUni = 100 .* abs(srpTrue - meanUni) ./ abs(srpTrue);
relErrImp = 100 .* abs(srpTrue - meanImp) ./ abs(srpTrue);
figure %[output:22eda1df]
tiledlayout(3,1) %[output:22eda1df]
nexttile %[output:22eda1df]
plot(log10(config.nMCintUni), relErrUni(:,1), 'rx-') %[output:22eda1df]
hold on %[output:22eda1df]
plot(log10(config.nMCintImp), relErrImp(:,1), 'bx-') %[output:22eda1df]
xlabel('log10(nMCint)'), ylabel('relative error, %') %[output:22eda1df]
ylim([0 100])
nexttile %[output:22eda1df]
plot(log10(config.nMCintUni), relErrUni(:,2), 'gx-') %[output:22eda1df]
hold on %[output:22eda1df]
plot(log10(config.nMCintImp), relErrImp(:,2), 'bx-') %[output:22eda1df]
xlabel('log10(nMCint)'), ylabel('relative error, %') %[output:22eda1df]
ylim([0 100])
nexttile %[output:22eda1df]
plot(log10(config.nMCintUni), relErrUni(:,3), 'bx-') %[output:22eda1df]
hold on %[output:22eda1df]
plot(log10(config.nMCintImp), relErrImp(:,3), 'bx-') %[output:22eda1df]
xlabel('log10(nMCint)'), ylabel('relative error, %') %[output:22eda1df]
legend('uniform', 'importance')
ylim([0 100])

gFigs(config.gFigs);
%[text] ##

